// Ordena los KPIs por magnitud del cambio y separa mejoras de caidas
const RELEVANTE = 5, FUERTE = 15;
const kpis = $input.first().json.kpis || [];
const esBueno = (k) => k.mejor === 'abajo' ? k.variacion < 0 : k.variacion > 0;
const mejoras = [], caidas = [], revisar = [];
for (const k of kpis) {
  const v = Math.abs(k.variacion || 0);
  if (v < RELEVANTE) continue;
  if (esBueno(k)) mejoras.push(k); else {
    caidas.push(k);
    if (v >= FUERTE) revisar.push(k);
  }
}
const linea = (k) => `- ${k.etiqueta}: ${k.valor}${k.unidad} (${k.variacion > 0 ? '+' : ''}${k.variacion} %)`;
const texto = [
  'Reporte semanal · Club STEM', '',
  'Lo que mejoró:', ...mejoras.map(linea), '',
  'Lo que bajó:', ...caidas.map(linea), '',
  'Qué revisar esta semana:',
  ...(revisar.length ? revisar.map(linea)
      : ['Sin caídas relevantes: buen momento para probar algo nuevo.']),
].join('\n');
return [{ json: { texto, mejoras: mejoras.length, caidas: caidas.length, revisar: revisar.length } }];
